CREATE OR REPLACE FUNCTION public.execution_workspace_members(_workspace uuid) RETURNS TABLE(user_id uuid,display_name text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_workspace_role(_workspace,'viewer') THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN QUERY SELECT m.user_id,coalesce(p.display_name,'Team member') FROM public.workspaces w JOIN public.organization_members m ON m.org_id=w.org_id LEFT JOIN public.profiles p ON p.user_id=m.user_id WHERE w.id=_workspace AND public.execution_user_allowed(_workspace,m.user_id); END $$;
REVOKE ALL ON FUNCTION public.execution_workspace_members(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.execution_workspace_members(uuid) TO authenticated;
ALTER TABLE public.tasks ADD COLUMN recurrence_source_id uuid REFERENCES public.tasks(id); CREATE UNIQUE INDEX execution_recurrence_once ON public.tasks(recurrence_source_id) WHERE recurrence_source_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.repeat_execution_task(_task uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.tasks; nid uuid; nd date; BEGIN SELECT * INTO t FROM public.tasks WHERE id=_task FOR UPDATE; IF t.id IS NULL OR NOT public.has_workspace_role(t.workspace_id,'member') THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT id INTO nid FROM public.tasks WHERE recurrence_source_id=_task; IF nid IS NOT NULL THEN RETURN nid; END IF; IF t.status<>'done' OR t.recurrence='none' OR t.due_date IS NULL THEN RAISE EXCEPTION 'Complete a recurring task with a due date first'; END IF; nd:=CASE WHEN t.recurrence='weekly' THEN t.due_date+7 ELSE (t.due_date+interval '1 month')::date END; INSERT INTO public.tasks(org_id,workspace_id,title,description,priority,due_date,project_id,campaign_id,owner_id,labels,recurrence,recurrence_source_id) VALUES(t.org_id,t.workspace_id,t.title,t.description,t.priority,nd,t.project_id,t.campaign_id,t.owner_id,t.labels,t.recurrence,t.id) RETURNING id INTO nid; RETURN nid; END $$;
REVOKE ALL ON FUNCTION public.repeat_execution_task(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.repeat_execution_task(uuid) TO authenticated;